import java.util.ArrayList;

ArrayList<String> names = new ArrayList<>();
names.add("Ana");
names.add("Jess");

System.out.println(names.size());              // 2
System.out.println(names.get(1));              // Jess
System.out.println(names.get(0).toUpperCase());   // ANA

public static <T extends Comparable<T>> T larger(T a, T b) {
    return a.compareTo(b) >= 0 ? a : b;
}

System.out.println(larger(3, 9));                 // 9
System.out.println(larger("apple", "banana"));    // banana
